const constructGetClasses = ({props}) => (stylesState = {}) => {
  let addedState = '';
  for (let state in stylesState)
    if (!!stylesState[state]) addedState += ' ' + state;
  const newClasses = Object.assign ({}, props.classes);
  for (let className in newClasses)
    newClasses[className] += addedState;
  return newClasses;
};

const constructGetAnchor = ({props, React}) => anchorParams => {
  const combinedProps = {...anchorParams, ...props};
  const {anchors} = combinedProps;
  return ({children, name}) => {
    if (!anchors || !anchors[name]) return children;
    const AnchorOverride = anchors[name];
    return React.createElement (AnchorOverride, {
      ...combinedProps,
      original: children,
    });
  };
};

module.exports = function (Component) {
  const {React, injectSheet} = this.imports;
  const {defaultStyles} = Component;

  const WithUtils = props => {
    return React.createElement (Component, {
      ...props,
      getClasses: constructGetClasses ({props}),
      getAnchor: constructGetAnchor ({props, React}),
    });
  };

  return props => {
    const styles = this.mergeStyles (defaultStyles, props.styles, {});
    const ComponentWithSheet = injectSheet (styles) (WithUtils);
    return React.createElement (ComponentWithSheet, props);
  };
};
